window.__errs=[]; const ce=console.error; console.error=(...a)=>{ __errs.push(a.map(x=>String(x&&x.message||x)).join(' ').slice(0,90)); ce(...a); };
const skip=n=>!n.parentElement||n.parentElement.closest('script,style,svg,textarea,select,title,[translate=no],.notranslate,font[data-t]');
const wrap=n=>{ if(!n.nodeValue.trim()||!n.isConnected||skip(n)) return; const a=document.createElement('font'); a.setAttribute('data-t','1'); const b=document.createElement('font'); b.textContent=n.nodeValue; a.appendChild(b); n.parentNode.replaceChild(a,n); };
const all=()=>{ const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT); const ns=[]; for(let n=w.nextNode();n;n=w.nextNode()) ns.push(n); ns.forEach(wrap); };
all(); new MutationObserver(()=>{ clearTimeout(window.__tt); window.__tt=setTimeout(all,120); }).observe(document.body,{childList:true,subtree:true,characterData:true});
return {wrapped: document.querySelectorAll('font[data-t]').length > 100};

